@app.get("/local-blob/<key>")
def local_blob(key):
    """Secours UNIQUEMENT pour le développement local sans compte Vercel
    Blob. En production, les logos sont servis directement depuis l'URL
    Vercel Blob (CDN public), cette route n'est alors jamais utilisée."""
    data = blob_read_local(key)
    if data is None:
        return jsonify({"error": "Introuvable"}), 404
    return send_file(io.BytesIO(data), mimetype="application/octet-stream")


@app.post("/api/generate")
@login_required
def generate_report():
    raw_payload = request.form.get("payload")
    if not raw_payload:
        return jsonify({"error": "payload manquant"}), 400
    try:
        payload = json.loads(raw_payload)
    except ValueError:
        return jsonify({"error": "payload JSON invalide"}), 400

    photos = []
    i = 0
    while True:
        f = request.files.get(f"photo_{i}")
        if f is None:
            break
        photos.append(f.read())
        i += 1

    logo_file = request.files.get("logo")
    logo_bytes = logo_file.read() if logo_file else None

    try:
        docx_bytes = build_report_docx(payload, photos, logo_bytes=logo_bytes)
    except Exception as e:
        return jsonify({"error": f"Échec de la génération du rapport : {e}"}), 500

    filename = (payload.get("filename") or "rapport").strip() or "rapport"
    if not filename.lower().endswith(".docx"):
        filename += ".docx"

    return Response(
        docx_bytes,
        mimetype="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


